create table public.enterprise_partner_campaign_outcomes (id uuid primary key default gen_random_uuid(), campaign_id uuid not null references public.enterprise_partner_campaigns(id) on delete cascade, partner_business_id uuid references public.businesses(id) on delete set null, metric_date date not null default current_date, visits bigint not null default 0, check_ins bigint not null default 0, reviews bigint not null default 0, preferred_uses bigint not null default 0, access_redemptions bigint not null default 0, promotion_redemptions bigint not null default 0, attributed_users bigint not null default 0, points_awarded bigint not null default 0, unique(campaign_id,partner_business_id,metric_date));
create index enterprise_partner_campaign_outcomes_idx on public.enterprise_partner_campaign_outcomes(campaign_id,metric_date desc);
alter table public.enterprise_partner_campaign_outcomes enable row level security;
create or replace function public.record_enterprise_partner_campaign_outcome(p_campaign_id uuid,p_partner_business_id uuid,p_visits bigint default 0,p_check_ins bigint default 0,p_reviews bigint default 0,p_preferred_uses bigint default 0,p_access_redemptions bigint default 0,p_promotion_redemptions bigint default 0,p_attributed_users bigint default 0,p_points_awarded bigint default 0) returns public.enterprise_partner_campaign_outcomes language plpgsql security definer set search_path=public as $$ declare o public.enterprise_partner_campaign_outcomes; begin if not exists(select 1 from public.enterprise_partner_campaigns c join public.enterprise_partner_networks n on n.id=c.network_id where c.id=p_campaign_id and n.owner_business_id in(select business_id from public.business_members where user_id=auth.uid())) then raise exception 'campaign access denied'; end if; insert into public.enterprise_partner_campaign_outcomes(campaign_id,partner_business_id,visits,check_ins,reviews,preferred_uses,access_redemptions,promotion_redemptions,attributed_users,points_awarded) values(p_campaign_id,p_partner_business_id,greatest(p_visits,0),greatest(p_check_ins,0),greatest(p_reviews,0),greatest(p_preferred_uses,0),greatest(p_access_redemptions,0),greatest(p_promotion_redemptions,0),greatest(p_attributed_users,0),greatest(p_points_awarded,0)) on conflict(campaign_id,partner_business_id,metric_date) do update set visits=excluded.visits,check_ins=excluded.check_ins,reviews=excluded.reviews,preferred_uses=excluded.preferred_uses,access_redemptions=excluded.access_redemptions,promotion_redemptions=excluded.promotion_redemptions,attributed_users=excluded.attributed_users,points_awarded=excluded.points_awarded returning * into o; return o; end $$;
create or replace function public.get_partner_campaign_roi(p_campaign_id uuid,p_start date default current_date-30,p_end date default current_date) returns table(partner_business_id uuid,visits bigint,check_ins bigint,reviews bigint,preferred_uses bigint,access_redemptions bigint,promotion_redemptions bigint,attributed_users bigint,points_awarded bigint,engagement_score numeric,conversion_rate numeric) language sql security definer set search_path=public as $$ select o.partner_business_id,sum(o.visits),sum(o.check_ins),sum(o.reviews),sum(o.preferred_uses),sum(o.access_redemptions),sum(o.promotion_redemptions),sum(o.attributed_users),sum(o.points_awarded),round((sum(o.check_ins)*.25+sum(o.reviews)*.15+sum(o.preferred_uses)*.2+sum(o.access_redemptions)*.2+sum(o.promotion_redemptions)*.2)::numeric,2),round(case when sum(o.visits)>0 then sum(o.check_ins)::numeric/sum(o.visits)*100 else 0 end,2) from public.enterprise_partner_campaign_outcomes o join public.enterprise_partner_campaigns c on c.id=o.campaign_id join public.enterprise_partner_networks n on n.id=c.network_id where o.campaign_id=p_campaign_id and o.metric_date between p_start and p_end and n.owner_business_id in(select business_id from public.business_members where user_id=auth.uid()) group by o.partner_business_id order by round((sum(o.check_ins)*.25+sum(o.reviews)*.15+sum(o.preferred_uses)*.2+sum(o.access_redemptions)*.2+sum(o.promotion_redemptions)*.2)::numeric,2) desc $$;
create or replace function public.get_partner_network_benchmark(p_network_id uuid,p_start date default current_date-30,p_end date default current_date) returns table(partner_business_id uuid,partner_visits bigint,partner_checkins bigint,partner_reviews bigint,partner_preferred bigint,partner_access bigint,partner_promotions bigint,checkin_rate numeric,review_rate numeric,engagement_score numeric) language sql security definer set search_path=public as $$ with m as (select o.partner_business_id,sum(o.visits) visits,sum(o.check_ins) checkins,sum(o.reviews) reviews,sum(o.preferred_uses) preferred,sum(o.access_redemptions) access,sum(o.promotion_redemptions) promotions from public.enterprise_partner_campaign_outcomes o join public.enterprise_partner_campaigns c on c.id=o.campaign_id where c.network_id=p_network_id and o.metric_date between p_start and p_end group by o.partner_business_id) select partner_business_id,visits,checkins,reviews,preferred,access,promotions,round(case when visits>0 then checkins::numeric/visits*100 else 0 end,2),round(case when checkins>0 then reviews::numeric/checkins*100 else 0 end,2),round((checkins*.25+reviews*.15+preferred*.2+access*.2+promotions*.2)::numeric,2) from m order by round((checkins*.25+reviews*.15+preferred*.2+access*.2+promotions*.2)::numeric,2) desc $$;
revoke all on function public.record_enterprise_partner_campaign_outcome(uuid,uuid,bigint,bigint,bigint,bigint,bigint,bigint,bigint,bigint) from public,anon; revoke all on function public.get_partner_campaign_roi(uuid,date,date) from public,anon; revoke all on function public.get_partner_network_benchmark(uuid,date,date) from public,anon; grant execute on function public.record_enterprise_partner_campaign_outcome(uuid,uuid,bigint,bigint,bigint,bigint,bigint,bigint,bigint,bigint) to authenticated; grant execute on function public.get_partner_campaign_roi(uuid,date,date) to authenticated; grant execute on function public.get_partner_network_benchmark(uuid,date,date) to authenticated;
